            var result=new ArrayList<Map<String,Object>>();for(var original:analyses){var analysis=new LinkedHashMap<>(original);var input=new LinkedHashMap<>(object(original.get("input")));input.remove("path");input.put("prepared_json",prepared.get(text(analysis.get("id"))).toString());analysis.put("input",input);result.add(analysis);}
            var root=new LinkedHashMap<String,Object>();root.put("schema_version",1);root.put("edition",edition);root.put("analyses",result);root.put("maximum_cells",maximumCells);root.put("maximum_components",maximumComponents);root.put("maximum_waypoints",maximumWaypoints);root.put("maximum_matrix_cells",maximumMatrixCells);root.put("maximum_edges",maximumEdges);root.put("python_hash_seed",pythonHashSeed);return root;
