                if(options.get("terminal_states")!=null){var terminals=new HashSet<String>();var annotations=new HashSet<String>();Boolean labelled=null;for(Object raw:list(options.get("terminal_states"))){var terminal=object(raw);allowed(terminal,"cell","annotation");require(terminals.add(data(terminal.get("cell")))&&terminals.size()<=100000,"Terminal cell IDs must be unchanged and unique");boolean annotated=terminal.containsKey("annotation");if(labelled==null)labelled=annotated;require(labelled==annotated,"Use either all annotated or all unannotated terminal IDs");if(annotated)require(annotations.add(data(terminal.get("annotation"))),"Duplicate terminal annotations are outside the unambiguous export profile");}require(!terminals.isEmpty(),"Empty explicit terminal list is not automatic detection; use null if intended");}
                integer(options.get("knn"),1,100000);var waypoints=object(options.get("waypoints"));allowed(waypoints,"count","cells");require(waypoints.containsKey("count")!=waypoints.containsKey("cells"),"Declare waypoint count OR exact cell IDs");if(waypoints.containsKey("count"))integer(waypoints.get("count"),1,1000000);else require(!identities(waypoints.get("cells"),1000000).isEmpty(),"Require a nonempty explicit waypoint family");bool(options.get("scale_components"));bool(options.get("use_early_cell_as_start"));integer(options.get("max_iterations"),1,100000);integer(options.get("seed"),0,4294967295L);require(Set.of("fail","retain-pseudotime-only").contains(text(options.get("empty_fates"))),"Declare fail versus retain-pseudotime-only for source empty-fate outcomes");
